demo.css:
p { font: 20px var(--demo-mono); white-space: pre; margin: 10px 0; }
u { text-decoration-color: var(--demo-accent); text-decoration-thickness: 2px; }
.none u { text-decoration-skip-spaces: none; }
.se u { text-decoration-skip-spaces: start end; }
.all u { text-decoration-skip-spaces: all; }
